  MANAGER = 'Manager',
  CHEF = 'Chef',
  WAITER = 'Waiter',
  BARISTA = 'Barista',
  OPEN = 'Open Shift'
}

export enum ShiftStatus {
  DRAFT = 'Draft',
  PUBLISHED = 'Published',
  LATE = 'Late for Clock In',
  COMPLETED = 'Completed'
}

