import React from 'react';
import { ChevronLeft, ChevronRight } from 'lucide-react';
import { Employee, Shift, ShiftStatus } from '../types';
import { EMPLOYEES } from '../constants';

interface DailyListViewProps {
  shifts: Shift[];
  currentDate: Date;
  onChangeDate: (delta: number) => void;
  onEditShift: (shift: Shift) => void;
}

const DailyListView: React.FC<DailyListViewProps> = ({ shifts, currentDate, onChangeDate, onEditShift }) => {

  const getEmployee = (id: string) => EMPLOYEES.find(e => e.id === id);

  const formatDate = (date: Date) => {
    return date.toLocaleDateString('en-US', { month: 'long', day: 'numeric', year: 'numeric' });
  };

  const isToday = (date: Date) => {
    const today = new Date();
    return date.getDate() === today.getDate() &&
      date.getMonth() === today.getMonth() &&
      date.getFullYear() === today.getFullYear();
  };

  return (
    <div className="flex flex-col h-full bg-gray-50">
      {/* Date Navigator */}
      <div className="bg-green-600 px-4 py-3 flex items-center justify-between text-white shadow-md z-10 sticky top-0">
        <button 
          onClick={() => onChangeDate(-1)}
          className="p-1 rounded-full hover:bg-green-700 transition"
        >
          <ChevronLeft size={24} />
        </button>
        <span className="font-semibold text-lg">
          {isToday(currentDate) ? "Today" : formatDate(currentDate)}
        </span>
        <button 
          onClick={() => onChangeDate(1)}
          className="p-1 rounded-full hover:bg-green-700 transition"
        >
          <ChevronRight size={24} />
        </button>
      </div>

      {/* List Content */}
      <div className="flex-1 overflow-y-auto p-4 space-y-3 pb-24">
        {shifts.length === 0 ? (
          <div className="text-center text-gray-400 mt-10">
            <p>No shifts scheduled for this day.</p>
          </div>
        ) : (
          shifts.map((shift) => {
            const employee = getEmployee(shift.employeeId);
            if (!employee) return null;

            const isLate = shift.status === ShiftStatus.LATE;

            return (
              <div 
                key={shift.id} 
                onClick={() => onEditShift(shift)}
                className={`bg-white rounded-xl shadow-sm border-l-4 p-4 flex items-center cursor-pointer hover:shadow-md transition active:scale-[0.99] ${isLate ? 'border-red-500' : 'border-green-500'}`}
              >
                {/* Avatar */}
                <div className="mr-4 flex-shrink-0">
                  <img 
                    src={employee.avatar} 
                    alt={employee.name} 
                    className="w-14 h-14 rounded-full object-cover border border-gray-100"
                  />
                </div>

                {/* Details */}
                <div className="flex-1 min-w-0">
                  <h3 className="font-bold text-gray-800 text-lg truncate">{employee.name}</h3>
                  <p className="text-gray-500 text-sm truncate">{shift.location}</p>
                  <p className="text-gray-500 text-sm truncate">{shift.role}</p>
                </div>

                {/* Time & Status */}
                <div className="text-right flex-shrink-0 ml-2">
                  <p className="font-bold text-gray-800 text-lg tabular-nums">
                    {shift.startTime} - {shift.endTime}
                  </p>
                  <p className="text-xs text-gray-400 mt-0.5">{formatDate(currentDate)}</p>
                  <p className={`text-xs font-semibold mt-1 ${isLate ? 'text-red-500' : 'text-gray-400'}`}>
                    {shift.status}
                  </p>
                </div>
              </div>
            );
          })
        )}
      </div>
    </div>
  );
};

export default DailyListView;

import React from 'react';
import { Clock, Plus, AlertTriangle, DollarSign } from 'lucide-react';
import { Employee, Shift, Role, ShiftStatus } from '../types';
import { EMPLOYEES } from '../constants';

interface WeeklyTimetableViewProps {
  shifts: Shift[];
  currentDate: Date;
  onAddShift: (employeeId: string, date: string) => void;
}

const WeeklyTimetableView: React.FC<WeeklyTimetableViewProps> = ({ shifts, currentDate, onAddShift }) => {

  // Helper to get days of the week starting from current date (or start of week)
  const getWeekDays = (baseDate: Date) => {
    const days = [];
    const startOfWeek = new Date(baseDate);
    // Adjust to Monday
    const day = startOfWeek.getDay();
    const diff = startOfWeek.getDate() - day + (day === 0 ? -6 : 1); 
    startOfWeek.setDate(diff);

    for (let i = 0; i < 7; i++) {
      const d = new Date(startOfWeek);
      d.setDate(startOfWeek.getDate() + i);
      days.push(d);
    }
    return days;
  };

  const weekDays = getWeekDays(currentDate);

  const formatDateKey = (date: Date) => date.toISOString().split('T')[0];

  const getShiftsForCell = (employeeId: string, date: Date) => {
    const dateKey = formatDateKey(date);
    return shifts.filter(s => s.employeeId === employeeId && s.date === dateKey);
  };

  const getRoleColor = (role: Role) => {
    switch (role) {
      case Role.MANAGER: return 'bg-red-500 text-white';
      case Role.CHEF: return 'bg-orange-500 text-white';
      case Role.WAITER: return 'bg-purple-600 text-white';
      case Role.BARISTA: return 'bg-blue-500 text-white';
      case Role.OPEN: return 'bg-black text-white';
      default: return 'bg-gray-500 text-white';
    }
  };

  return (
    <div className="flex flex-col h-full bg-white overflow-hidden text-sm">
      {/* Filters Bar */}
      <div className="flex flex-wrap items-center gap-2 p-3 bg-gray-100 border-b border-gray-200">
        <div className="bg-white border rounded px-3 py-1.5 text-gray-600 flex items-center min-w-[150px]">
           <span className="mr-2">👤</span> Select Staff
        </div>
        <div className="bg-white border rounded px-3 py-1.5 text-gray-600 flex items-center min-w-[150px]">
           <span className="mr-2">📍</span> Bourke St Cafe
        </div>
        <div className="flex-1"></div>
        <div className="bg-white border rounded px-3 py-1.5 text-gray-600 flex items-center">
           <span className="mr-2">✓</span> By Staff
        </div>
        <div className="bg-white border rounded px-3 py-1.5 text-gray-600 flex items-center">
           <span className="mr-2">📅</span> All Shifts
        </div>
      </div>

      {/* Grid Container */}
      <div className="flex-1 overflow-auto">
        <div className="min-w-[1000px]">
          {/* Header Row */}
          <div className="grid grid-cols-[250px_repeat(7,1fr)] sticky top-0 z-20 shadow-sm">
            <div className="bg-gray-200 p-3 font-semibold text-gray-600 border-r border-b border-white">
              EMPLOYEE NAME
            </div>
            {weekDays.map((day, idx) => (
              <div key={idx} className="bg-gray-200 p-2 border-r border-b border-white">
                <div className="font-semibold text-gray-600 uppercase text-xs">
                  {day.toLocaleDateString('en-US', { weekday: 'short' })} {day.getDate()}/{day.getMonth() + 1}
                </div>
              </div>
            ))}
          </div>

          {/* Rows */}
          {EMPLOYEES.map((employee) => (
            <div key={employee.id} className="grid grid-cols-[250px_repeat(7,1fr)] hover:bg-gray-50">
              {/* Employee Column */}
              <div className="p-3 border-r border-b border-gray-100 flex items-start gap-3 bg-white sticky left-0 z-10">
                {employee.id === 'open' ? (
                  <div className="w-10 h-10 rounded-full bg-black text-white flex items-center justify-center font-bold text-lg flex-shrink-0">?</div>
                ) : (
                  <img src={employee.avatar} alt={employee.name} className="w-10 h-10 rounded-full object-cover flex-shrink-0" />
                )}
                <div className="min-w-0">
                  <div className="font-medium text-gray-800 truncate">{employee.name}</div>
                  {employee.id === 'open' ? (
                    <div className="flex items-center text-xs text-gray-500 mt-1">
                      <Clock size={12} className="mr-1" />
                      <span>21.00</span>
                    </div>
                  ) : (
                    <div className="flex items-center text-xs text-gray-500 mt-1 gap-2">
                       <span className="flex items-center"><Clock size={12} className="mr-1"/> 40.00</span>
                       {employee.hourlyRate && <span className="flex items-center"><DollarSign size={12} className="mr-1"/> {employee.hourlyRate}</span>}
                    </div>
                  )}
                </div>
              </div>

              {/* Day Columns */}
              {weekDays.map((day, idx) => {
                const cellShifts = getShiftsForCell(employee.id, day);
                const isPast = day < new Date(new Date().setHours(0,0,0,0));

                return (
                  <div key={idx} className={`p-1 border-r border-b border-gray-100 relative group min-h-[100px] flex flex-col gap-1 ${isPast ? 'bg-gray-50/50' : ''}`}>

                    {/* Ghost Add Button */}
                    <div className="absolute inset-0 flex items-center justify-center opacity-0 group-hover:opacity-100 transition-opacity pointer-events-none">
                       <button 
                        onClick={() => onAddShift(employee.id, formatDateKey(day))}
                        className="bg-gray-100 rounded-full p-2 pointer-events-auto hover:bg-gray-200"
                       >
                         <Plus size={20} className="text-gray-400" />
                       </button>
                    </div>

                    {cellShifts.map(shift => (
                      <div key={shift.id} className="bg-white p-2 rounded border border-gray-200 shadow-sm relative z-10">
                        <div className="text-xs text-gray-500 mb-1 truncate">{shift.location}</div>
                        <span className={`inline-block px-2 py-0.5 rounded text-xs font-bold mb-1 ${getRoleColor(shift.role)}`}>
                          {shift.role}
                        </span>
                        <div className="flex items-center justify-between">
                          <span className="text-xs font-medium text-gray-700">
                             {shift.startTime} - {shift.endTime}
                          </span>
                          {shift.status === ShiftStatus.LATE && (
                             <AlertTriangle size={14} className="text-red-500" />
                          )}
                        </div>
                         <div className="text-[10px] text-gray-400 mt-1">
                            ({shift.duration}h)
                         </div>
                      </div>
                    ))}
                  </div>
                );
              })}
            </div>
          ))}
        </div>
      </div>
    </div>
  );
};

export default WeeklyTimetableView;

import React, { useState } from 'react';
import { X, Mail, Check, Copy } from 'lucide-react';

interface ShareModalProps {
  isOpen: boolean;
  onClose: () => void;
  rosterDateRange: string;
}

const ShareModal: React.FC<ShareModalProps> = ({ isOpen, onClose, rosterDateRange }) => {
  const [email, setEmail] = useState('');
  const [isSent, setIsSent] = useState(false);

  if (!isOpen) return null;

  const handleSend = (e: React.FormEvent) => {
    e.preventDefault();
    // Mock send
    setTimeout(() => {
      setIsSent(true);
      setTimeout(() => {
        setIsSent(false);
        onClose();
        setEmail('');
      }, 2000);
    }, 800);
  };

  return (
    <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50 p-4">
      <div className="bg-white rounded-xl shadow-2xl max-w-md w-full overflow-hidden transform transition-all">
        <div className="bg-green-600 px-6 py-4 flex justify-between items-center">
          <h2 className="text-white font-bold text-lg flex items-center gap-2">
            <Mail size={20} /> Share Roster
          </h2>
          <button onClick={onClose} className="text-white hover:bg-green-700 rounded-full p-1">
            <X size={20} />
          </button>
        </div>

        <div className="p-6">
          {isSent ? (
            <div className="flex flex-col items-center justify-center py-8 text-center animate-pulse">
              <div className="w-16 h-16 bg-green-100 rounded-full flex items-center justify-center mb-4">
                <Check size={32} className="text-green-600" />
              </div>
              <h3 className="text-xl font-bold text-gray-800">Sent Successfully!</h3>
              <p className="text-gray-500 mt-2">The roster for {rosterDateRange} has been emailed.</p>
            </div>
          ) : (
            <>
              <p className="text-gray-600 mb-6">
                Send the roster for <span className="font-semibold text-gray-800">{rosterDateRange}</span> to your staff or management.
              </p>

              <form onSubmit={handleSend} className="space-y-4">
                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-1">Email Address</label>
                  <input 
                    type="email" 
                    required
                    value={email}
                    onChange={(e) => setEmail(e.target.value)}
                    placeholder="staff@example.com"
                    className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-green-500 focus:border-green-500 outline-none transition"
                  />
                </div>

                <div className="flex items-center justify-between p-3 bg-gray-50 rounded-lg border border-gray-200">
                   <div className="flex items-center gap-2 text-sm text-gray-500">
                     <Copy size={14} /> <span>Copy public link</span>
                   </div>
                   <button type="button" className="text-green-600 text-sm font-semibold hover:underline">Copy</button>
                </div>

                <div className="pt-2">
                  <button 
                    type="submit"
                    className="w-full bg-green-600 hover:bg-green-700 text-white font-bold py-3 rounded-lg shadow-md transition transform active:scale-95 flex justify-center items-center gap-2"
                  >
                    Send Email
                  </button>
                </div>
              </form>
            </>
          )}
        </div>
      </div>
    </div>
  );
};

export default ShareModal;

import React, { useState, useEffect } from 'react';
import { Calendar, Filter, Plus, Share2, Menu, LayoutList, CalendarDays } from 'lucide-react';
import DailyListView from './components/DailyListView';
import WeeklyTimetableView from './components/WeeklyTimetableView';
import ShareModal from './components/ShareModal';
import { ViewMode, Shift } from './types';
import { MOCK_SHIFTS } from './constants';

const App: React.FC = () => {
  const [viewMode, setViewMode] = useState<ViewMode>('daily');
  const [currentDate, setCurrentDate] = useState(new Date());
  const [shifts, setShifts] = useState<Shift[]>(MOCK_SHIFTS);
  const [isShareModalOpen, setIsShareModalOpen] = useState(false);

  // Filter shifts based on current view
  const filteredShifts = shifts.filter(shift => {
    if (viewMode === 'daily') {
      const shiftDate = shift.date; // YYYY-MM-DD
      const current = currentDate.toISOString().split('T')[0];
      return shiftDate === current;
    }
    // For weekly, we pass all and let the component handle grid placement
    return true; 
  });

  const handleDateChange = (delta: number) => {
    const newDate = new Date(currentDate);
    newDate.setDate(newDate.getDate() + delta);
    setCurrentDate(newDate);
  };

  const handleAddShift = (employeeId?: string, date?: string) => {
    // Mock addition
    const newShift: Shift = {
      id: Math.random().toString(36).substr(2, 9),
      employeeId: employeeId || 'open',
      startTime: '09:00',
      endTime: '17:00',
      date: date || currentDate.toISOString().split('T')[0],
      location: 'Bourke St Cafe',
      role: employeeId === 'open' ? 'Open Shift' as any : 'Manager' as any,
      status: 'Draft' as any,
      duration: 8
    };
    setShifts([...shifts, newShift]);
    alert("New shift draft created!");
  };

  // Calculate Date Range String for Header
  const getDateRangeString = () => {
    if (viewMode === 'daily') {
      return currentDate.toLocaleDateString('en-US', { weekday: 'short', month: 'short', day: 'numeric' });
    } else {
      const start = new Date(currentDate);
      const day = start.getDay();
      const diff = start.getDate() - day + (day === 0 ? -6 : 1); 
      start.setDate(diff);
      const end = new Date(start);
      end.setDate(start.getDate() + 6);
      return `${start.toLocaleDateString('en-US', { month: 'short', day: 'numeric' })} - ${end.toLocaleDateString('en-US', { month: 'short', day: 'numeric', year: 'numeric' })}`;
    }
  };

  return (
    <div className="h-screen w-full flex flex-col bg-gray-100 max-w-[1600px] mx-auto shadow-2xl overflow-hidden relative">

      {/* Top Header */}
      <header className="bg-white border-b border-gray-200 px-4 py-3 flex items-center justify-between shrink-0 h-16">
        <div className="flex items-center gap-3">
          <div className="w-8 h-8 bg-green-100 text-green-600 rounded flex items-center justify-center">
            <Calendar size={20} />
          </div>
          <h1 className="text-xl font-bold text-green-600 tracking-tight">ROSTER</h1>
          <span className="text-gray-400 text-sm hidden sm:block">| {getDateRangeString()}</span>
        </div>

        <div className="flex items-center gap-2 sm:gap-4">
          {/* View Toggles */}
          <div className="bg-gray-100 p-1 rounded-lg flex items-center mr-2">
             <button 
               onClick={() => setViewMode('daily')}
               className={`p-1.5 rounded-md transition ${viewMode === 'daily' ? 'bg-white shadow text-green-600' : 'text-gray-500 hover:text-gray-700'}`}
               title="Daily List View"
             >
               <LayoutList size={18} />
             </button>
             <button 
               onClick={() => setViewMode('weekly')}
               className={`p-1.5 rounded-md transition ${viewMode === 'weekly' ? 'bg-white shadow text-green-600' : 'text-gray-500 hover:text-gray-700'}`}
               title="Weekly Timetable View"
             >
               <CalendarDays size={18} />
             </button>
          </div>

          <button className="text-gray-500 hover:text-green-600 transition">
            <Filter size={22} />
          </button>

          <button 
            onClick={() => setIsShareModalOpen(true)}
            className="text-gray-500 hover:text-green-600 transition"
            title="Share Roster"
          >
            <Share2 size={22} />
          </button>

          <button 
            onClick={() => handleAddShift()}
