import { DB_CONFIG } from '../config';
import { Shift, ShiftStatus, Employee, DbRoster } from '../types';
import { DB_STAFF, DB_ROLES, DB_SHIFTS_DEF, DB_ROSTER } from '../constants';

// Helper to assign colors based on staff ID/Index (Deterministic)
const COLORS = [
  'bg-blue-100 text-blue-700',
  'bg-emerald-100 text-emerald-700',
  'bg-purple-100 text-purple-700',
  'bg-amber-100 text-amber-700',
  'bg-rose-100 text-rose-700',
  'bg-indigo-100 text-indigo-700',
  'bg-cyan-100 text-cyan-700'
];

class DatabaseService {
  private connected = false;
  // In-memory mock tables
  private rosterTable: DbRoster[] = [...DB_ROSTER];

  async connect(): Promise<boolean> {
    console.log(`[MySQL] Connecting to ${DB_CONFIG.host}...`);
    await new Promise(resolve => setTimeout(resolve, 1000)); // Simulate latency

    if (DB_CONFIG.password === 'Linna32@#') {
      this.connected = true;
      console.log(`[MySQL] Connected to database: ${DB_CONFIG.database}`);
      return true;
    }
    throw new Error('Access Denied');
  }

  // Mimics "SELECT * FROM staff"
  async getEmployees(): Promise<Employee[]> {
    this.ensureConnection();

    // Simulate query delay
    await new Promise(resolve => setTimeout(resolve, 300));

    return DB_STAFF.map((s, index) => {
      // Logic to determine initials and colors (frontend specific)
      const initials = s.staff_id === 999 ? '?' : `${s.first_name[0]}${s.last_name[0]}`;
      const color = s.staff_id === 999 ? 'bg-gray-900 text-white' : COLORS[index % COLORS.length];

      return {
        id: s.staff_id.toString(),
        name: s.staff_id === 999 ? 'Open Shifts' : `${s.first_name} ${s.last_name}`,
        initials,
        color,
        defaultRole: 'Staff',
        defaultLocation: 'Bourke St Cafe'
      };
    });
  }

  // Mimics "SELECT * FROM vw_weekly_roster" (Joining tables)
  async getShifts(): Promise<Shift[]> {
    this.ensureConnection();
    console.log('[MySQL] EXEC: SELECT * FROM vw_weekly_roster');
    await new Promise(resolve => setTimeout(resolve, 600));

    // Perform JOINs in memory
    return this.rosterTable.map(r => {
      const staff = DB_STAFF.find(s => s.staff_id === r.staff_id);
      const role = DB_ROLES.find(role => role.role_id === r.role_id);
      const shiftDef = DB_SHIFTS_DEF.find(def => def.shift_id === r.shift_id);

      if (!staff || !role || !shiftDef) {
        console.warn('Orphaned roster entry', r);
        return null;
      }

      // Calculate duration
      const start = parseInt(shiftDef.start_time.split(':')[0]);
      const end = parseInt(shiftDef.end_time.split(':')[0]);

      // Basic time formatting HH:mm
      const fmtTime = (t: string) => t.substring(0, 5);

      return {
        id: r.roster_id.toString(),
        employeeId: r.staff_id.toString(),
        startTime: fmtTime(shiftDef.start_time),
        endTime: fmtTime(shiftDef.end_time),
        date: r.roster_date,
        location: 'Bourke St Cafe', // Not in roster schema, defaulting
        role: role.role_name,
        status: ShiftStatus.PUBLISHED, // Not in roster schema, defaulting
        duration: end - start,
        notes: r.notes || undefined
      };
    }).filter(s => s !== null) as Shift[];
  }

  async addShift(shift: Shift): Promise<void> {
    this.ensureConnection();
    // Reverse map UI shift to DB Roster
    // In a real app, you'd insert into `roster` table
    const newId = Math.floor(Math.random() * 100000);

    console.log(`[MySQL] INSERT INTO roster SET staff_id=${shift.employeeId}, roster_date='${shift.date}'...`);

    // For the mock to work, we need to map back to a valid shift_id/role_id
    // Defaults for demo:
    const defaultShiftDef = DB_SHIFTS_DEF.find(s => s.shift_name === 'Standard') || DB_SHIFTS_DEF[0];
    const defaultRole = DB_ROLES.find(r => r.role_name === 'Manager') || DB_ROLES[0];

    this.rosterTable.push({
      roster_id: newId,
      staff_id: parseInt(shift.employeeId),
      role_id: defaultRole.role_id,
      day_id: new Date(shift.date).getDay(), // Approximate
      shift_id: defaultShiftDef.shift_id,
      roster_date: shift.date,
      notes: ''
    });

    await new Promise(resolve => setTimeout(resolve, 500));
  }

  private ensureConnection() {
    if (!this.connected) {
      throw new Error('Database not connected.');
    }
  }
}

export const db = new DatabaseService();

import React from 'react';
import { ChevronLeft, ChevronRight } from 'lucide-react';
import { Employee, Shift, ShiftStatus } from '../types';

interface DailyListViewProps {
  shifts: Shift[];
  employees: Employee[]; // Passed as prop now
  currentDate: Date;
  onChangeDate: (delta: number) => void;
  onEditShift: (shift: Shift) => void;
}

const DailyListView: React.FC<DailyListViewProps> = ({ shifts, employees, currentDate, onChangeDate, onEditShift }) => {

  const getEmployee = (id: string) => employees.find(e => e.id === id);

  const formatDate = (date: Date) => {
    return date.toLocaleDateString('en-US', { month: 'long', day: 'numeric', year: 'numeric' });
  };

  const isToday = (date: Date) => {
    const today = new Date();
    return date.getDate() === today.getDate() &&
      date.getMonth() === today.getMonth() &&
      date.getFullYear() === today.getFullYear();
  };

  return (
    <div className="flex flex-col h-full bg-gray-50">
      {/* Date Navigator */}
      <div className="bg-green-600 px-4 py-3 flex items-center justify-between text-white shadow-md z-10 sticky top-0">
        <button 
          onClick={() => onChangeDate(-1)}
          className="p-1 rounded-full hover:bg-green-700 transition"
        >
          <ChevronLeft size={24} />
        </button>
        <span className="font-semibold text-lg">
          {isToday(currentDate) ? "Today" : formatDate(currentDate)}
        </span>
        <button 
          onClick={() => onChangeDate(1)}
          className="p-1 rounded-full hover:bg-green-700 transition"
        >
          <ChevronRight size={24} />
        </button>
      </div>

      {/* List Content */}
      <div className="flex-1 overflow-y-auto p-4 space-y-3 pb-24">
        {shifts.length === 0 ? (
          <div className="text-center text-gray-400 mt-10">
            <p>No shifts scheduled for this day.</p>
          </div>
        ) : (
          shifts.map((shift) => {
            const employee = getEmployee(shift.employeeId);
            if (!employee) return null;

            const isLate = shift.status === ShiftStatus.LATE;

            return (
              <div 
                key={shift.id} 
                onClick={() => onEditShift(shift)}
                className={`bg-white rounded-xl shadow-sm border-l-4 p-4 flex items-center cursor-pointer hover:shadow-md transition active:scale-[0.99] ${isLate ? 'border-red-500' : 'border-green-500'}`}
              >
                {/* Initials Avatar */}
                <div className="mr-4 flex-shrink-0">
                  <div className={`w-14 h-14 rounded-full flex items-center justify-center text-lg font-bold shadow-sm ${employee.color}`}>
                    {employee.initials}
                  </div>
                </div>

                {/* Details */}
                <div className="flex-1 min-w-0">
                  <h3 className="font-bold text-gray-800 text-lg truncate">{employee.name}</h3>
                  <p className="text-gray-500 text-sm truncate">{shift.location}</p>
                  <p className="text-gray-500 text-sm truncate">{shift.role}</p>
                </div>

                {/* Time & Status */}
                <div className="text-right flex-shrink-0 ml-2">
                  <p className="font-bold text-gray-800 text-lg tabular-nums">
                    {shift.startTime} - {shift.endTime}
                  </p>
                  <p className="text-xs text-gray-400 mt-0.5">{formatDate(currentDate)}</p>
                  <p className={`text-xs font-semibold mt-1 ${isLate ? 'text-red-500' : 'text-gray-400'}`}>
                    {shift.status}
                  </p>
                </div>
              </div>
            );
          })
        )}
      </div>
    </div>
  );
};

